const FAQItem = ({ id, question, answer }) => {
  const [isOpen, setIsOpen] = useState(false);
  const contentId = `content-${id}`;

  return (
    <div className="example">
      <button
        id={`btn-${id}`}
        type="button"
        aria-expanded={isOpen}
        aria-controls={contentId}
        className="question-button"
        onClick={() => setIsOpen(!isOpen)}
      >
        <span>{question}</span>
        <svg
          className="icon"
          width="20"
          height="20"
          viewBox="0 0 20 20"
          fill="currentColor"
          aria-hidden="true"
        >
          <path
            fillRule="evenodd"
            d="M5.293 7.293a1 1 0 011.414 0L10 10.586l3.293-3.293a1 1 0 111.414 1.414l-4 4a1 1 0 01-1.414 0l-4-4a1 1 0 010-1.414z"
            clipRule="evenodd"
          />
        </svg>
      </button>
      <div
        id={contentId}
        role="region"
        aria-labelledby={`btn-${id}`}
        className="details"
        hidden={!isOpen}
      >
        {answer}
      </div>
    </div>
  );
};

const App = () => {
  const faqs = [
    {
      id: "purr",
      question: "Why do cats purr?",
      answer: "While often a sign of contentment, cats also purr to communicate, self-soothe, and even heal. The frequency of a cat's purr (25-150 Hertz) has been shown to improve bone density and promote tendon repair."
    },
    {
      id: "whiskers",
      question: "Why do cats have whiskers?",
      answer: "Whiskers are highly sensitive tactile hairs called vibrissae. They help cats navigate in the dark, detect changes in air currents, and determine if they can fit through tight spaces."
    },
    {
      id: "sleep",
      question: "Why do cats sleep so much?",
      answer: "Cats are crepuscular predators, meaning they are most active at dawn and dusk. They conserve energy by sleeping 12-16 hours a day to be ready for short, intense bursts of hunting."
    },
    {
      id: "feet",
      question: "Do cats always land on their feet?",
      answer: "Cats have a 'righting reflex' that allows them to twist their bodies in mid-air. While they often land on their feet, it depends on the height of the fall and their reaction time; falls from very low or very high heights can still be dangerous."
    }
  ];

  return (
    <main>
      <h1>Feline Frequently Asked Questions</h1>
      <div className="faq-container">
        {faqs.map((faq) => (
          <FAQItem key={faq.id} {...faq} />
        ))}
      </div>
    </main>
  );
};

const root = ReactDOM.createRoot(document.getElementById('root'));
root.render(<App />);
